            C#

    // C# program to reverse a linked list in groups

using System;
using System.Collections.Generic;

class Node {
    public int data;
    public Node next;

    public Node(int x) {
        data = x;
        next = null;
    }
}

class GfG {

    // Function to reverse the linked list in groups 
    static Node reverseKGroup(Node head, int k) {
        if (head == null || k == 1)
            return head;

        List<Node> q = new List<Node>();
        Node curr = head;

        while (curr != null) {
            int count = 0;

            // Store addresses of the k nodes in the list
            while (count < k && curr != null) {
                q.Add(curr);
                curr = curr.next;
                count++;
            }

            // Swap first and last nodes in the list
            while (q.Count > 0) {
                Node front = q[0];
                Node last = q[q.Count - 1];

                // Swapping data between the front and last nodes
                int temp = front.data;
                front.data = last.data;
                last.data = temp;

                // Remove from the front and back of the list
                q.RemoveAt(0);
                if (q.Count > 0) {
                    q.RemoveAt(q.Count - 1);
                }
            }
        }

        return head;
    }

    static void printList(Node head) {
        Node curr = head;
        while (curr != null) {
            Console.Write(curr.data + " ");
            curr = curr.next;
        }
        Console.WriteLine();
    }

    static void Main(string[] args) {

        // Creating a sample singly linked list:
        // 1 -> 2 -> 3 -> 4 -> 5 -> 6
        Node head = new Node(1);
        head.next = new Node(2);
        head.next.next = new Node(3);
        head.next.next.next = new Node(4);
        head.next.next.next.next = new Node(5);
        head.next.next.next.next.next = new Node(6);

        head = reverseKGroup(head, 3);

        printList(head);
    }
}


            JavaScript

    // JavaScript program to reverse a linked 
// list in groups of given size

class Node {
    constructor(x) {
        this.data = x;
        this.next = null;
    }
}

// Function to reverse the linked list
// in groups using deque
function reverseKGroup(head, k) {
    if (!head || k === 1) {
        return head;
    }

    let dq = [];
    let curr = head;

    while (curr) {
        let count = 0;

        // Push k nodes into the deque
        while (curr && count < k) {
            dq.push(curr);
            curr = curr.next;
            count++;
        }

        // Swap first and last nodes in the deque
        while (dq.length) {
            let front = dq[0];
            let last = dq[dq.length - 1];
            [front.data, last.data] = [last.data, front.data];
            dq.shift(); 
            dq.pop(); 
        }
    }

    return head;
}

